// Pulls every contact under the 36 valid mon-yy-rep tags (felix, alvi, jack —
// samprit/toby/emon are not sales reps and are intentionally not tracked here),
// buckets each into a result-focused status, and hands off one flat array of
// rows to the next node for a single bulk upsert into Supabase.
//
// Only "apr-26-felix"-style 3-letter-month tags are read. Longer variants like
// "april-26-felix" are a naming-drift mistake and are deliberately not matched.

const GHL_KEY = 'PASTE_YOUR_GHL_PRIVATE_INTEGRATION_TOKEN_HERE'; // or wire via an n8n credential
const LOCATION_ID = 'hWIN3ZJnvbKKE45XinlK';

const YEAR_2DIGIT = new Date().getFullYear() % 100;
const REPS = ['felix', 'alvi', 'jack'];
const MONTHS = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];

// stageId -> result-focused bucket. Built from the stages actually observed
// on tagged contacts, live, on 2026-08-27 — not the full generic stage list.
// A stage that shows up later and isn't in this map falls through to
// 'unmapped' rather than being silently dropped or miscounted.
const STAGE_BUCKET = {
  'ae4c86f0-374b-421c-a14e-f000906ea509': 'new',              // Symbio: 00 - All New Lead
  'e6908723-1c55-4e27-bf14-52a01b569869': 'new',              // Cold Caller - Alvi: 00 - All New Lead
  '270adb1a-9c64-4919-ba94-3642ae6e06bc': 'new',              // Jack TBS: 00 - All New Lead
  '8a8afdf9-5259-45bc-9cc4-12a734bff257': 'new',              // Campbellfield: 00 - Lead Made
  'df2182be-dc96-4789-8ca0-49e76c747e33': 'new',              // AI Sophia: To be Called
  '733a7672-5db5-4bef-ba25-8216eb523705': 'working',          // BDM: Pending Future Opportunities
  '08e46dcf-18d9-486e-bb6f-90df69318b67': 'working',          // BDM: On Hold
  '316a5d01-55e0-42b0-9180-f7b343cac38c': 'working',          // BDM: Hot Lead - Callback ASAP
  'e9b2494b-3cdf-4bd8-9584-a36ee72bd209': 'working',          // BDM: Pending Prepare Proposal
  '131f289e-45e5-4a18-a648-b5e6b1f59d17': 'appointment_booked', // BDM: Confirmed Appointment
  '705f8a6b-77e0-46dc-bdf1-f074c46e3f03': 'appointment_booked', // BDM: Face-to-face Meeting In Progress
  'b42e0498-766c-4db3-92ae-12322cb3e49d': 'appointment_booked', // Symbio: 07 - Qualified Appointment Booked $200+
  '5b687e21-bae8-4423-a819-29d63d5e11b9': 'proposal_sent',    // BDM: Proposal Sent - Awaiting Responses
  '329ae774-756c-4602-9201-3af16068c81f': 'proposal_sent',    // BDM: 48 Hours Follow Email
  '66980d97-ffe9-47a5-a4ec-5eeebc1686dd': 'won',              // BDM: Project Sold
  'e3f8e471-bec1-45c6-add2-03c60e60c698': 'lost',             // BDM: Deal Lost
  'c1398d35-e96f-4f5c-8fbd-3fab33ef2653': 'closed_unclear',   // Jack NBN: Closed (won/lost not distinguished)
};

const byKey = new Map(); // dedupe contacts that carry more than one month tag — keep the latest

for (const rep of REPS) {
  for (const mon of MONTHS) {
    const tag = `${mon}-${YEAR_2DIGIT}-${rep}`;
    const monthNum = String(MONTHS.indexOf(mon) + 1).padStart(2, '0');
    const tagMonth = `20${YEAR_2DIGIT}-${monthNum}-01`;

    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://services.leadconnectorhq.com/contacts/search',
      headers: {
        Authorization: `Bearer ${GHL_KEY}`,
        Version: '2021-07-28',
        'Content-Type': 'application/json',
      },
      body: {
        locationId: LOCATION_ID,
        pageLimit: 100,
        filters: [{ field: 'tags', operator: 'contains', value: tag }],
      },
      json: true,
    });

    for (const contact of res.contacts || []) {
      for (const o of contact.opportunities || []) {
        const key = `${contact.id}::${o.id}`;
        const existing = byKey.get(key);
        if (existing && existing.tag_month >= tagMonth) continue; // keep latest tag
        byKey.set(key, {
          contact_id: contact.id,
          opportunity_id: o.id,
          phone: contact.phone || null,
          rep,
          tag,
          tag_month: tagMonth,
          stage_id: o.pipelineStageId,
          stage_bucket: STAGE_BUCKET[o.pipelineStageId] || 'unmapped',
          opportunity_status: o.status,
          synced_at: new Date().toISOString(),
        });
      }
    }
  }
}

return [{ json: { rows: Array.from(byKey.values()) } }];
